SELECT l.id, CASE WHEN r.reaped_at IS NOT NULL THEN 'process reaped' WHEN r.released_at IS NOT NULL THEN 'session ended' WHEN l.opened AND act.observed_at IS NULL THEN 'session never reached mike' WHEN l.opened THEN 'session went quiet' ELSE 'never started' END AS reason, CASE WHEN r.released_at IS NOT NULL OR NOT l.opened THEN TRUE END AS exited FROM launch.launches l LEFT JOIN sessions.sessions s ON s.session_uuid = l.session_uuid LEFT JOIN workspace.session_registrations r ON r.session_id = s.id LEFT JOIN LATERAL runtime.session_activity(s.id) act ON TRUE WHERE l.closed_at IS NULL AND (r.released_at >= l.created_at OR (l.created_at < now() - interval '24 hours' AND (r.session_id IS NULL OR r.released_at IS NOT NULL) AND NOT COALESCE(act.observed_at >= now() - interval '24 hours', FALSE)))
